import { launchProfile } from '../browser-pool/client';
import { writeFileSync } from 'node:fs';
const c=await launchProfile('test-results/s122-high-road/profile',{headless:true,args:['--use-angle=metal'],viewport:{width:1280,height:720}});
const p=c.pages()[0]??await c.newPage();const errors:string[]=[];p.on('pageerror',e=>errors.push(e.message));await p.addInitScript('window.__name=f=>f');
const url='http://127.0.0.1:4981/?testApi=1&scenelab=1&renderer=webgl&quality=high&audio=muted';
const start=async()=>{await p.goto(url);await p.waitForFunction(()=>!!window.__SS__);await p.evaluate(()=>window.__SS__!.ready);await p.getByTestId('start-game').click();await p.getByTestId('level-L9').click();await p.waitForFunction(()=>window.__SS__!.missions.state()?.id==='L9');if(await p.getByTestId('mission-button').isVisible())await p.getByTestId('mission-button').click();await p.waitForFunction(()=>window.__SS__!.missions.state()?.phase==='playing');};
const state=()=>p.evaluate(()=>({tick:window.__SS__!.tick(),hp:window.__SS__!.getEntity(1)!.health.current,level:window.__SS__!.missions.state()?.id,quality:window.__SS__!.getState().render.quality}));
try{await start();const before=await state();await p.evaluate(()=>{const g=(window as any).__SCENE__.game;g.world.player.damage(1000,g.world.tick,true);window.__SS__!.pause();});const dead=await state();if(!await p.getByTestId('pause-settings').isVisible())await p.keyboard.press('Escape');await p.getByTestId('pause-settings').click();await p.getByTestId('setting-quality').selectOption('low');const changedDead=await state();await p.getByTestId('settings-back').click();await p.getByTestId('resume-game').click();await p.waitForFunction(()=>window.__SS__!.getEntity(1)!.health.current>0,{},{timeout:30000});const alive=await state();if(!await p.getByTestId('pause-settings').isVisible())await p.keyboard.press('Escape');await p.getByTestId('pause-settings').click();await p.getByTestId('setting-quality').selectOption('high');await p.getByTestId('settings-back').click();await p.getByTestId('resume-game').click();await p.waitForTimeout(800);const after=await state();await start();await p.waitForTimeout(800);const continued=await state();writeFileSync('test-results/s122-save.json',JSON.stringify({method:'Continue existing L9-default profile; controlled lethal diagnostic hit and pause at zero HP; physical settings changes and menu reload/Continue',before,dead,changedDead,alive,after,continued,errors},null,2));}finally{await c.close();}

